:root { font-family: system-ui, sans-serif; color: #18283e; background: #f4f6fa; }
* { box-sizing: border-box; }
body { margin: 0; }
main { max-width: 760px; margin: 64px auto; padding: 32px; background: white; border-radius: 12px; box-shadow: 0 4px 24px #18283e0d; }
h1 { margin-top: 0; overflow-wrap: anywhere; }
h2 { margin-top: 32px; font-size: 1.2rem; }
label { display: block; font-weight: 600; margin-bottom: 8px; }
.input-line { display: flex; gap: 12px; }
input { min-width: 0; flex: 1; border: 1px solid #788698; border-radius: 6px; padding: 10px; font: inherit; }
button { background: #2455b3; color: white; border: 0; border-radius: 6px; padding: 11px 16px; font: inherit; cursor: pointer; }
button:hover { background: #1a4088; }
button:focus-visible, input:focus-visible, a:focus-visible { outline: 3px solid #cb8500; outline-offset: 3px; }
.projects { padding: 0; list-style: none; }
.projects li { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 16px 0; border-bottom: 1px solid #dce2eb; }
.projects span { overflow-wrap: anywhere; min-width: 0; }
.projects form { flex-shrink: 0; }
.error { color: #a21d24; font-weight: 600; }
@media (max-width: 600px) { main { margin: 16px; padding: 24px; } .input-line { flex-direction: column; } }

